I could not read spe/evals/harness/r03-workflow.js. I assumed it runs one trial with `python3 spe/evals/harness/run_trial.py --config spe/evals/configs/<id>.yaml --ticket <id> --trial <k> --out <dir>`. That command writes output.json and transcript.jsonl and prints cost_usd. I also assumed that `grade.py --answers <file> --output <file>` prints JSON with category_ok and priority_ok, and that ticket IDs are in spe/evals/tasks/tickets.jsonl.

**Gates before launch**

I run four gates in order, and I stop if any one fails.

1. **Grader selftest.** I build an oracle from spe/evals/tasks/answers.json. grade.py must score it 50/50 on both label.category and label.priority. It must fail an empty output and a wrong-label output on all 50 tickets. I also run judge.md on 2 replies with known good tone and 2 with known bad tone, and it must sort them correctly.
2. **Control.** I regrade round 3's saved outputs with today's grade.py. The numbers must match the r03 rows in spe/prediction-log.md. If they differ, the grader has changed. I halt and log that as a failure.
3. **Dry run on 3 cells.** I launch this script with `{dryRunCells: [3 cells], trials: 1}`. The 3 cells are B and C2 on the first ticket in tickets.jsonl, plus C2 on the second ticket. The run writes to spe/evals/runs/r04-dry. Every record must have a peek verdict, both grader booleans and a tone verdict. I pass the measured cost per trial back in as `estTrialUsd`.
4. **Prediction unchanged.** `git diff --quiet HEAD -- spe/predictions/r04.yaml spe/plans/r04.md` must pass.

Then I commit the script as `SPE r04 evaluate (harness)` and launch it with `{estTrialUsd: <measured>}`.

**spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'spe-r04-eval',
  description: 'SPE round 4 eval. Configs B and C2 on 50 tickets, 5 trials per cell. Code grader first, Opus tone judge second. Spend cap $40.',
  phases: [
    { title: 'Manifest' },
    { title: 'Trials' },
    { title: 'Split cells' },
    { title: 'Analysis' },
  ],
};

// The round number lives here only. Every prompt and path derives from it.
const ROUND = 4;
const RR = `r${String(ROUND).padStart(2, '0')}`;
const MODEL = 'opus';

const A = typeof args === 'object' && args !== null ? args : {};
const DRY = Array.isArray(A.dryRunCells) && A.dryRunCells.length > 0 ? A.dryRunCells : null;
const CAP_USD = A.capUsd ?? 40;
const TRIALS = A.trials ?? (DRY ? 1 : 5);
const EXTRA_CAP = DRY ? 0 : (A.extraTrialCap ?? 5);
const CHUNK = A.chunk ?? 25;
const EXPECTED_TICKETS = 50;

// Unmeasured estimates. The dry run measures trialUsd, and it comes back in through args.
const EST = {
  trialUsd: A.estTrialUsd ?? 0.03, // system under test, per ticket run
  judgeUsd: A.estJudgeUsd ?? 0.01, // Opus tone judge, per reply
  agentUsd: A.estAgentUsd ?? 0.25, // Workflow agent overhead, per agent call
};

const CONFIGS = {
  B: { file: 'spe/evals/configs/B.yaml', desc: '12-line prompt, 6 tools' },
  C2: { file: 'spe/evals/configs/C2.yaml', desc: '12-line prompt, 3 tools plus a separate check_status tool' },
};
const RUN_DIR = `spe/evals/runs/${RR}${DRY ? '-dry' : ''}`;
const ANSWERS = 'spe/evals/tasks/answers.json';
const GRADER = 'spe/evals/graders/grade.py';
const JUDGE = 'spe/evals/graders/judge.md';
const FORBIDDEN = ['spe/evals/graders', ANSWERS, 'spe/predictions', 'spe/plans', 'spe/prediction-log.md', 'spe/failures.md'];
const PEEK_RE = 'evals/graders|answers\\.json|spe/predictions|spe/plans|prediction-log\\.md|failures\\.md';

// ---------- Budget ----------
let spent = 0; // measured runner cost plus estimated agent and judge cost
let held = 0; // estimates reserved for work in flight
const skips = [];
const voids = [];
const records = [];
let halt = null;

function hold(label, est) {
  if (spent + held + est > CAP_USD) {
    skips.push({ label, est_usd: +est.toFixed(2), spent_usd: +spent.toFixed(2) });
    log(`SKIP ${label}: est $${est.toFixed(2)} would cross the $${CAP_USD} cap (spent $${spent.toFixed(2)}, held $${held.toFixed(2)})`);
    return false;
  }
  held += est;
  return true;
}
function settle(est, actual) {
  held -= est;
  spent += actual;
}

async function ask(prompt, opts) {
  try {
    return await agent(prompt, { model: MODEL, ...opts });
  } catch (e) {
    log(`AGENT FAILED ${opts.label}: ${e && e.message ? e.message : e}`);
    return null;
  }
}

// ---------- Schemas ----------
const MANIFEST_SCHEMA = {
  type: 'object',
  properties: { tickets: { type: 'array', items: { type: 'string' } } },
  required: ['tickets'],
};
const RUN_SCHEMA = {
  type: 'object',
  properties: {
    runs: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          ticket: { type: 'string' },
          status: { type: 'string', enum: ['ok', 'error'] },
          out_dir: { type: 'string' },
          cost_usd: { type: 'number' },
          error: { type: 'string' },
        },
        required: ['ticket', 'status', 'out_dir', 'cost_usd'],
      },
    },
  },
  required: ['runs'],
};
const CHECK_SCHEMA = {
  type: 'object',
  properties: {
    checks: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          out_dir: { type: 'string' },
          peek: { type: 'string', enum: ['none', 'mention', 'read'] },
          peek_target: { type: 'string' },
          grader_status: { type: 'string', enum: ['ok', 'error', 'not_run'] },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          grader_error: { type: 'string' },
        },
        required: ['out_dir', 'peek', 'grader_status'],
      },
    },
  },
  required: ['checks'],
};
const JUDGE_SCHEMA = {
  type: 'object',
  properties: {
    verdicts: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          out_dir: { type: 'string' },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
        required: ['out_dir', 'tone_pass', 'reason'],
      },
    },
  },
  required: ['verdicts'],
};
const FAILURE_SCHEMA = {
  type: 'object',
  properties: {
    types: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          name: { type: 'string' },
          kind: { type: 'string', enum: ['model', 'config', 'harness', 'grader', 'task'] },
          configs: { type: 'array', items: { type: 'string' } },
          count: { type: 'number' },
          what: { type: 'string' },
          how_to_spot: { type: 'string' },
          example_out_dirs: { type: 'array', items: { type: 'string' } },
          matches_existing: { type: 'string' },
        },
        required: ['name', 'kind', 'configs', 'count', 'what', 'how_to_spot', 'example_out_dirs', 'matches_existing'],
      },
    },
  },
  required: ['types'],
};
const CRITIC_SCHEMA = {
  type: 'object',
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'string' } },
    prediction_map: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          metric: { type: 'string' },
          config: { type: 'string' },
          measured: { type: ['number', 'null'] },
          grader_check: { type: 'string' },
        },
        required: ['metric', 'config', 'measured', 'grader_check'],
      },
    },
  },
  required: ['complete', 'gaps', 'prediction_map'],
};
const WRITE_SCHEMA = {
  type: 'object',
  properties: { path: { type: 'string' }, bytes: { type: 'number' } },
  required: ['path', 'bytes'],
};

// ---------- Prompts ----------
function runPrompt(u) {
  const c = CONFIGS[u.config];
  return [
    `You operate the SPE round ${ROUND} harness. You run trials. You do not grade them.`,
    `Config ${u.config} (${c.desc}). Trial index ${u.trial}.`,
    `Tickets: ${u.tickets.join(', ')}.`,
    `For each ticket, run exactly this command:`,
    `  python3 spe/evals/harness/run_trial.py --config ${c.file} --ticket <TICKET> --trial ${u.trial} --out ${RUN_DIR}/${u.config}/<TICKET>/t${u.trial}`,
    `Each run writes output.json and transcript.jsonl into its --out folder and prints cost_usd on its last line.`,
    `If a run fails, retry it once. Report the summed cost of both attempts. If it fails again, report status "error" with the last stderr line.`,
    `Do not open, list, search, or print anything under: ${FORBIDDEN.join(', ')}.`,
    `Do not edit, rerun, or inspect outputs beyond reading the printed cost.`,
    `Return one record per ticket.`,
  ].join('\n');
}

function checkPrompt(dirs) {
  return [
    `You run code checks for SPE round ${ROUND}. Use commands only. Do not judge tone. Do not edit any file.`,
    `Out dirs:`,
    ...dirs.map((d) => `  ${d}`),
    `Step 1 is the peek scan. For each out dir run: grep -oE '${PEEK_RE}' <out_dir>/transcript.jsonl | sort -u`,
    `If nothing matches, set peek "none". If a match sits inside a tool call that opened, listed, or searched that path, set peek "read" and put the path in peek_target. If the string only appears in text, set peek "mention".`,
    `Step 2 is grading. For dirs with peek "read", set grader_status "not_run". For every other dir run:`,
    `  python3 ${GRADER} --answers ${ANSWERS} --output <out_dir>/output.json`,
    `Copy category_ok and priority_ok from its JSON exactly. Do not override the grader.`,
    `If it exits non-zero or prints no JSON, set grader_status "error" and copy the last stderr line into grader_error.`,
  ].join('\n');
}

function judgePrompt(dirs) {
  return [
    `You judge reply tone for SPE round ${ROUND}. Read ${JUDGE} once and apply it as written.`,
    `For each out dir below, read only the "reply" field of <out_dir>/output.json.`,
    `Do not read label fields, transcripts, ${ANSWERS}, or grader code.`,
    ...dirs.map((d) => `  ${d}`),
    `Return tone_pass for each out dir. Add a one-sentence reason that names the judge.md criterion you applied.`,
  ].join('\n');
}

// ---------- Pipeline stages ----------
async function stageRun(u) {
  const r = await ask(runPrompt(u), {
    label: `run ${u.config} t${u.trial} ${u.tickets[0]}..${u.tickets.at(-1)}`,
    phase: u.phase,
    schema: RUN_SCHEMA,
  });
  if (!r) {
    // Unknown spend, so count the full estimate.
    const runs = u.tickets.map((ticket) => ({
      ticket, status: 'error', out_dir: `${RUN_DIR}/${u.config}/${ticket}/t${u.trial}`, cost_usd: EST.trialUsd, error: 'harness agent failed',
    }));
    return { ...u, runs, sut: u.tickets.length * EST.trialUsd, agents: 1 };
  }
  const sut = r.runs.reduce((s, x) => s + (x.cost_usd || 0), 0);
  return { ...u, runs: r.runs, sut, agents: 1 };
}

async function stageCheck(u) {
  const dirs = u.runs.filter((x) => x.status === 'ok').map((x) => x.out_dir);
  if (!dirs.length) return { ...u, checks: [] };
  const c = await ask(checkPrompt(dirs), {
    label: `check ${u.config} t${u.trial} ${u.tickets[0]}..`,
    phase: u.phase,
    schema: CHECK_SCHEMA,
  });
  return { ...u, checks: c ? c.checks : [], agents: u.agents + 1 };
}

async function stageJudge(u) {
  const dirs = u.checks.filter((c) => c.peek !== 'read' && c.grader_status === 'ok').map((c) => c.out_dir);
  if (!dirs.length) return { ...u, verdicts: [] };
  const j = await ask(judgePrompt(dirs), {
    label: `judge ${u.config} t${u.trial} ${u.tickets[0]}..`,
    phase: u.phase,
    schema: JUDGE_SCHEMA,
    model: 'opus',
  });
  return { ...u, verdicts: j ? j.verdicts : [], agents: u.agents + 1 };
}

function collect(u) {
  const checks = new Map(u.checks.map((c) => [c.out_dir, c]));
  const tones = new Map(u.verdicts.map((v) => [v.out_dir, v]));
  for (const r of u.runs) {
    const rec = {
      config: u.config, ticket: r.ticket, trial: u.trial, extra: u.trial > TRIALS,
      out_dir: r.out_dir, status: r.status, cost_usd: r.cost_usd,
    };
    const c = checks.get(r.out_dir);
    if (r.status !== 'ok') {
      // A crashed trial produced no label, so it fails every check.
      Object.assign(rec, { category_ok: false, priority_ok: false, both_ok: false, tone_pass: false, error: r.error });
    } else if (!c) {
      rec.void = 'check agent returned no record';
    } else if (c.peek === 'read') {
      rec.void = `peeked: ${c.peek_target || 'unknown path'}`;
      if ((c.peek_target || '').includes('answers.json') && !halt) halt = `answer key leak in ${r.out_dir}`;
    } else if (c.grader_status !== 'ok') {
      rec.grader_error = c.grader_error || 'grader not run';
      if (!halt) halt = `broken grader on ${r.out_dir}: ${rec.grader_error}`;
    } else {
      const t = tones.get(r.out_dir);
      Object.assign(rec, {
        category_ok: c.category_ok,
        priority_ok: c.priority_ok,
        both_ok: c.category_ok === true && c.priority_ok === true,
        tone_pass: t ? t.tone_pass : null,
        tone_reason: t ? t.reason : 'no judge verdict',
        peek_mention: c.peek === 'mention',
      });
    }
    if (rec.void) voids.push({ config: rec.config, ticket: rec.ticket, trial: rec.trial, reason: rec.void });
    records.push(rec);
  }
}

// ---------- Waves ----------
function chunk(arr, n) {
  const out = [];
  for (let i = 0; i < arr.length; i += n) out.push(arr.slice(i, i + n));
  return out;
}

function unitsFor(cells, trial, phaseTitle) {
  const byConfig = {};
  for (const c of cells) (byConfig[c.config] ||= []).push(c.ticket);
  const units = [];
  for (const [config, tickets] of Object.entries(byConfig)) {
    for (const t of chunk(tickets, CHUNK)) units.push({ config, trial, tickets: t, phase: phaseTitle });
  }
  return units;
}

async function runWave(label, units) {
  const go = [];
  for (const u of units) {
    const est = u.tickets.length * (EST.trialUsd + EST.judgeUsd) + 3 * EST.agentUsd;
    if (hold(`${label} ${u.config} ${u.tickets[0]}..${u.tickets.at(-1)}`, est)) go.push({ ...u, est });
  }
  if (!go.length) return;
  const done = await pipeline(go, stageRun, stageCheck, stageJudge);
  for (const u of done) {
    settle(u.est, u.sut + u.agents * EST.agentUsd + u.verdicts.length * EST.judgeUsd);
    collect(u);
  }
  log(`${label}: ${go.length} of ${units.length} units ran. Spent about $${spent.toFixed(2)} of $${CAP_USD}.`);
  if (halt) log(`HALT after ${label}: ${halt}`);
}

function splitCells() {
  const m = new Map();
  for (const r of records) {
    if (r.void || r.grader_error) continue;
    const key = `${r.config}|${r.ticket}`;
    const v = m.get(key) || { config: r.config, ticket: r.ticket, pass: 0, n: 0 };
    v.n += 1;
    if (r.both_ok) v.pass += 1;
    m.set(key, v);
  }
  return [...m.values()].filter((v) => v.pass > 0 && v.pass < v.n).map(({ config, ticket }) => ({ config, ticket }));
}

function rate(rs, field) {
  const xs = rs.filter((r) => typeof r[field] === 'boolean');
  return xs.length ? +(xs.filter((r) => r[field]).length / xs.length).toFixed(3) : null;
}

function summarize(split) {
  const out = {};
  for (const config of Object.keys(CONFIGS)) {
    const all = records.filter((r) => r.config === config);
    // Headline numbers use base trials only, so they match what the prediction measured.
    const base = all.filter((r) => !r.extra && !r.void && !r.grader_error);
    const extra = all.filter((r) => r.extra && !r.void && !r.grader_error);
    out[config] = {
      trials_run: all.length,
      base_scored: base.length,
      voided: all.filter((r) => r.void).length,
      runner_errors: all.filter((r) => r.status === 'error').length,
      peek_mentions: all.filter((r) => r.peek_mention).length,
      category_acc: rate(base, 'category_ok'),
      priority_acc: rate(base, 'priority_ok'),
      both_acc: rate(base, 'both_ok'),
      tone_pass: rate(base, 'tone_pass'),
      split_cells: split.filter((c) => c.config === config).length,
      extra_trials: extra.length,
      extra_both_acc: rate(extra, 'both_ok'),
    };
  }
  return out;
}

// ---------- Main ----------
phase('Manifest');
let cells;
if (DRY) {
  cells = DRY;
  log(`Dry run on ${cells.length} cells into ${RUN_DIR}, ${TRIALS} trial each.`);
} else {
  const m = await ask(
    `List the ticket IDs for SPE round ${ROUND}. Read the "id" field of each line in spe/evals/tasks/tickets.jsonl and return them in file order. Do not open ${ANSWERS} or anything under spe/evals/graders.`,
    { label: 'manifest', phase: 'Manifest', schema: MANIFEST_SCHEMA },
  );
  spent += EST.agentUsd;
  const ids = m ? [...new Set(m.tickets)] : [];
  if (ids.length !== EXPECTED_TICKETS) {
    halt = `manifest has ${ids.length} tickets and the plan says ${EXPECTED_TICKETS}`;
    log(`HALT: ${halt}`);
    return { round: ROUND, halt, spent_usd_estimate: +spent.toFixed(2) };
  }
  cells = Object.keys(CONFIGS).flatMap((config) => ids.map((ticket) => ({ config, ticket })));
  log(`${cells.length} cells, ${TRIALS} trials each, cap $${CAP_USD}.`);
}

phase('Trials');
// One wave per trial index. A budget cut then drops the same trial index from both configs.
for (let k = 1; k <= TRIALS && !halt; k++) {
  await runWave(`trial ${k}`, unitsFor(cells, k, 'Trials'));
}

phase('Split cells');
const split = halt ? [] : splitCells();
log(`${split.length} split cells. Up to ${EXTRA_CAP} extra trials each.`);
for (let k = TRIALS + 1; k <= TRIALS + EXTRA_CAP && split.length && !halt; k++) {
  await runWave(`extra ${k}`, unitsFor(split, k, 'Split cells'));
}

phase('Analysis');
const summary = summarize(split);
const okRuns = records.filter((r) => r.status === 'ok' && typeof r.cost_usd === 'number');
const measuredTrialUsd = okRuns.length ? okRuns.reduce((s, r) => s + r.cost_usd, 0) / okRuns.length : null;
log(`Measured runner cost per trial: ${measuredTrialUsd === null ? 'none' : '$' + measuredTrialUsd.toFixed(4)}. Agent and judge spend are estimates.`);

let failures = null;
let critic = null;
if (!DRY) {
  const failing = records
    .filter((r) => !r.void && (r.both_ok === false || r.tone_pass === false))
    .slice(0, 150)
    .map(({ config, ticket, trial, out_dir, category_ok, priority_ok, tone_pass, tone_reason, error }) =>
      ({ config, ticket, trial, out_dir, category_ok, priority_ok, tone_pass, tone_reason, error }));

  if (failing.length && hold('failure analysis', 2 * EST.agentUsd)) {
    failures = await ask(
      [
        `You run failure analysis for SPE round ${ROUND}. Do not edit any file.`,
        `Failing trials (up to 150) follow as JSON. Read their output.json and transcript.jsonl. Compare labels with ${ANSWERS}.`,
        JSON.stringify(failing),
        `Group them into failure types. Read spe/failures.md and set matches_existing to the F-number when a type matches. Use "new" otherwise.`,
        `Use kind "grader" when the grader looks wrong. That is a failure type too.`,
      ].join('\n'),
      { label: 'failure analysis', phase: 'Analysis', schema: FAILURE_SCHEMA },
    );
    settle(2 * EST.agentUsd, 2 * EST.agentUsd);
  }

  if (hold('completeness critic', 2 * EST.agentUsd)) {
    critic = await ask(
      [
        `You are the completeness critic for SPE round ${ROUND}. Do not edit any file.`,
        `Read spe/predictions/${RR}.yaml read-only. For every predicted number, find the measured value in the summary below and name the grader check behind it. Use null when nothing measured it.`,
        `Then list gaps. Check that each of the ${cells.length} cells has ${TRIALS} base trials, or that every missing trial appears in the skips or voids. Check that every void has a reason. Check that every split cell got extra trials or a logged skip.`,
        `Summary: ${JSON.stringify(summary)}`,
        `Skips: ${JSON.stringify(skips)}`,
        `Voids: ${JSON.stringify(voids)}`,
        `Halt: ${JSON.stringify(halt)}`,
        `Failure types: ${JSON.stringify(failures)}`,
      ].join('\n'),
      { label: 'completeness critic', phase: 'Analysis', schema: CRITIC_SCHEMA },
    );
    settle(2 * EST.agentUsd, 2 * EST.agentUsd);
  }
}

const result = {
  round: ROUND,
  dry_run: !!DRY,
  halt,
  cap_usd: CAP_USD,
  spent_usd_estimate: +spent.toFixed(2),
  measured_trial_usd: measuredTrialUsd,
  summary,
  skips,
  voids,
  failures,
  critic,
  records,
};

let written = null;
if (hold('write results', EST.agentUsd)) {
  written = await ask(
    `Write the JSON below verbatim to ${RUN_DIR}/results.json. Create the folder if needed. Do not change any other file. Do not commit. Return the path and byte count.\n${JSON.stringify(result)}`,
    { label: 'write results', phase: 'Analysis', schema: WRITE_SCHEMA },
  );
  settle(EST.agentUsd, EST.agentUsd);
}

log(`Done. Halt: ${halt || 'none'}. Spent about $${spent.toFixed(2)} of $${CAP_USD}. Results: ${written ? written.path : 'not written'}.`);
return { ...result, results_file: written ? written.path : null };
```

The script does not commit anything. When the completion notice arrives, I commit `SPE r04 evaluate (results): <headline>`. Then I do the close-out from `spe/evals/runs/r04/results.json`.
